import{_ as a,o as s,c as n,a0 as t}from"./chunks/framework.jwovEGr5.js";const k=JSON.parse('{"title":"Day 15: TCP Socket과 Echo","description":"","frontmatter":{},"headers":[],"relativePath":"outta-space/project/Day-15-TCP-Socket과-Echo.md","filePath":"outta-space/project/Day-15-TCP-Socket과-Echo.md"}'),i={name:"outta-space/project/Day-15-TCP-Socket과-Echo.md"};function c(o,e,l,d,p,r){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="day-15-tcp-socket과-echo" tabindex="-1">Day 15: TCP Socket과 Echo <a class="header-anchor" href="#day-15-tcp-socket과-echo" aria-label="Permalink to &quot;Day 15: TCP Socket과 Echo&quot;">​</a></h1><p>Loopback 주소 <code>127.0.0.1:9090</code>에서 동작하는 blocking TCP echo server와 client를 구현했다. <code>nc</code>와 Bash <code>/dev/tcp</code>로 연결을 먼저 관찰한 뒤 C socket API로 같은 흐름을 구성했다.</p><h2 id="tcp와-endpoint" tabindex="-1">TCP와 endpoint <a class="header-anchor" href="#tcp와-endpoint" aria-label="Permalink to &quot;TCP와 endpoint&quot;">​</a></h2><p>IP address는 network에서 host 또는 interface를 식별하고, port는 host 안에서 communication endpoint를 구분한다. 이번 실습은 외부 interface가 아닌 현재 host 자신을 가리키는 loopback 주소를 사용했다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Server endpoint: 127.0.0.1:9090</span></span>
<span class="line"><span>Protocol: TCP</span></span></code></pre></div><p>TCP는 연결 지향적이고 전송 순서를 유지하는 byte stream이다. Application message boundary는 보존하지 않으므로 한 번의 <code>write()</code>와 한 번의 <code>read()</code>가 일대일로 대응한다고 가정할 수 없다.</p><h2 id="server-socket-lifecycle" tabindex="-1">Server socket lifecycle <a class="header-anchor" href="#server-socket-lifecycle" aria-label="Permalink to &quot;Server socket lifecycle&quot;">​</a></h2><p>Server는 다음 순서로 구성했다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>socket()</span></span>
<span class="line"><span>→ bind(127.0.0.1:9090)</span></span>
<span class="line"><span>→ listen()</span></span>
<span class="line"><span>→ accept()</span></span>
<span class="line"><span>→ read()/write()</span></span>
<span class="line"><span>→ close()</span></span></code></pre></div><p><code>socket(AF_INET, SOCK_STREAM, 0)</code>은 IPv4 TCP socket을 만들고 process에서 사용할 FD를 반환한다. <code>inet_pton()</code>으로 문자열 IPv4 주소를 <code>struct in_addr</code> 형식으로 변환하고, <code>htons()</code>로 port를 network byte order로 변환했다.</p><p><code>bind()</code>는 socket에 local address를 지정하고, <code>listen()</code>은 socket을 연결 요청을 기다리는 상태로 전환한다. <code>ss -ltnp</code>에서 <code>127.0.0.1:9090</code>의 <code>LISTEN</code> 상태를 확인했다.</p><h2 id="listening-fd와-connected-fd" tabindex="-1">Listening FD와 connected FD <a class="header-anchor" href="#listening-fd와-connected-fd" aria-label="Permalink to &quot;Listening FD와 connected FD&quot;">​</a></h2><p><code>accept()</code>는 listening socket에 도착한 연결 하나를 받아 새로운 connected FD를 반환한다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server_fd</span></span>
<span class="line"><span>→ 새로운 연결 요청을 받는 listening FD</span></span>
<span class="line"><span></span></span>
<span class="line"><span>client_fd</span></span>
<span class="line"><span>→ 특정 client와 데이터를 주고받는 connected FD</span></span></code></pre></div><p>Listening FD와 connected FD는 역할과 lifetime이 다르다. 이번 server는 client 하나만 처리한 뒤 <code>client_fd</code>, <code>server_fd</code> 순서로 정리한다.</p><h2 id="read-loop와-eof" tabindex="-1">Read loop와 EOF <a class="header-anchor" href="#read-loop와-eof" aria-label="Permalink to &quot;Read loop와 EOF&quot;">​</a></h2><p>Connected FD에서 <code>read()</code>를 반복하며 다음 반환값을 구분했다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>n &gt; 0   → n바이트 수신</span></span>
<span class="line"><span>n == 0  → peer가 송신 방향을 닫아 EOF 도달</span></span>
<span class="line"><span>n == -1 → 오류</span></span></code></pre></div><p>TCP는 byte stream이므로 한 번의 <code>read()</code>가 client가 보낸 전체 데이터를 반환한다고 보장하지 않는다. Buffer가 C string처럼 NUL-terminated 된다고 가정하지 않고 실제 길이 <code>n</code>을 기준으로 데이터를 처리했다.</p><h2 id="partial-write" tabindex="-1">Partial write <a class="header-anchor" href="#partial-write" aria-label="Permalink to &quot;Partial write&quot;">​</a></h2><p>한 번의 <code>write()</code>도 요청한 전체 길이를 모두 처리한다고 보장하지 않는다. 지금까지 전송한 길이 <code>sent</code>를 누적하면서 남은 영역을 반복해 전송했다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>전송 시작 위치 = buffer + sent</span></span>
<span class="line"><span>남은 길이      = n - sent</span></span></code></pre></div><p><code>write()</code>가 양수를 반환하면 그만큼 <code>sent</code>를 증가시켰다. <code>errno == EINTR</code>이면 같은 위치부터 재시도하고, 다른 오류나 전송 진척이 없는 경우에는 cleanup으로 이동했다.</p><h2 id="client와-half-close" tabindex="-1">Client와 half-close <a class="header-anchor" href="#client와-half-close" aria-label="Permalink to &quot;Client와 half-close&quot;">​</a></h2><p>Client는 다음 순서로 동작한다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>socket()</span></span>
<span class="line"><span>→ connect(127.0.0.1:9090)</span></span>
<span class="line"><span>→ argv message 전송</span></span>
<span class="line"><span>→ shutdown(SHUT_WR)</span></span>
<span class="line"><span>→ echo를 EOF까지 수신</span></span>
<span class="line"><span>→ close()</span></span></code></pre></div><p><code>connect()</code>는 원격 server endpoint와 TCP 연결을 만든다. 메시지를 모두 보낸 뒤 <code>shutdown(socket_fd, SHUT_WR)</code>을 호출해 송신 방향만 닫았다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client → Server 방향: EOF 전달</span></span>
<span class="line"><span>Server → Client 방향: 계속 열려 있어 echo 수신 가능</span></span></code></pre></div><p>Server는 EOF를 확인하고 echo 전송을 마친 뒤 connected FD를 닫는다. Client는 그 결과로 수신 방향의 EOF까지 확인할 수 있다.</p><h2 id="error-handling과-cleanup" tabindex="-1">Error handling과 cleanup <a class="header-anchor" href="#error-handling과-cleanup" aria-label="Permalink to &quot;Error handling과 cleanup&quot;">​</a></h2><p>각 socket API의 반환값을 검사하고, 열린 자원의 수에 따라 공통 cleanup label로 이동했다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cleanup_client</span></span>
<span class="line"><span>→ client_fd close</span></span>
<span class="line"><span>→ cleanup_server로 이어짐</span></span>
<span class="line"><span>→ server_fd close</span></span></code></pre></div><p><code>perror()</code>는 원래 오류가 발생한 지점에서 먼저 호출했다. Cleanup 중 <code>close()</code>가 <code>errno</code>를 변경하기 전에 실제 실패 원인을 기록하기 위해서다. Cleanup label로만 아래 방향으로 이동하는 제한적인 <code>goto</code>가 C system code의 중복 정리에 유용하다는 점도 확인했다.</p><h2 id="관찰" tabindex="-1">관찰 <a class="header-anchor" href="#관찰" aria-label="Permalink to &quot;관찰&quot;">​</a></h2><p>연결 상태는 다음 명령으로 확인했다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ltnp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;:9090&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tnp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;:9090&#39;</span></span></code></pre></div><p><code>LISTEN</code>과 <code>ESTABLISHED</code> 상태를 관찰했고, <code>strace</code>로 client의 system call 흐름을 확인했다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">strace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -yy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trace=socket,bind,listen,accept,connect,read,write,shutdown,close</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ./network/tcp-echo-client</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;hello echo&quot;</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>socket → connect → write → shutdown → read → EOF → close</span></span></code></pre></div><h2 id="linux-system-software-직무와의-연결" tabindex="-1">Linux System Software 직무와의 연결 <a class="header-anchor" href="#linux-system-software-직무와의-연결" aria-label="Permalink to &quot;Linux System Software 직무와의 연결&quot;">​</a></h2><p><code>sysmon-agent</code>에서는 collector가 만든 metric을 network thread가 TCP로 전달할 예정이다. 이번 실습에서 익힌 socket lifetime, byte-stream 처리, partial write, EOF와 cleanup은 해당 network path의 기반이 된다.</p><h2 id="learned" tabindex="-1">Learned <a class="header-anchor" href="#learned" aria-label="Permalink to &quot;Learned&quot;">​</a></h2><ul><li>TCP는 message가 아니라 순서가 유지되는 byte stream이다.</li><li>Server의 listening FD와 client별 connected FD는 역할이 다르다.</li><li><code>accept()</code>는 특정 client와 연결된 새로운 FD를 반환한다.</li><li><code>read() == 0</code>은 peer의 송신 방향에서 EOF가 도착했다는 뜻이다.</li><li><code>read()</code>와 <code>write()</code>는 application message 단위와 일치하지 않을 수 있다.</li><li>Partial write는 offset과 남은 길이를 갱신하며 처리한다.</li><li><code>shutdown(SHUT_WR)</code>로 수신 방향을 유지한 채 송신 완료를 알릴 수 있다.</li><li>공통 cleanup label로 여러 FD의 lifetime을 관리할 수 있다.</li></ul><h2 id="apis" tabindex="-1">APIs <a class="header-anchor" href="#apis" aria-label="Permalink to &quot;APIs&quot;">​</a></h2><ul><li><code>socket()</code></li><li><code>inet_pton()</code></li><li><code>htons()</code></li><li><code>bind()</code></li><li><code>listen()</code></li><li><code>accept()</code></li><li><code>connect()</code></li><li><code>read()</code></li><li><code>write()</code></li><li><code>shutdown()</code></li><li><code>close()</code></li></ul><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><ul><li><code>ss -ltnp</code></li><li><code>ss -tnp</code></li><li><code>strace -yy -e trace=...</code></li><li>Bash <code>/dev/tcp/127.0.0.1/9090</code></li></ul><h2 id="mistakes" tabindex="-1">Mistakes <a class="header-anchor" href="#mistakes" aria-label="Permalink to &quot;Mistakes&quot;">​</a></h2><ul><li>처음에는 <code>inet_pton()</code> 결과를 임시 <code>int</code>에 저장하려 했다. Destination은 <code>addr.sin_addr</code>여야 한다.</li><li>오류 분기마다 <code>close()</code>와 <code>return</code>을 반복해 cleanup 흐름이 복잡해졌다.</li><li>TCP 데이터를 NUL-terminated C string처럼 취급하기 쉬웠다.</li></ul><h2 id="todo" tabindex="-1">TODO <a class="header-anchor" href="#todo" aria-label="Permalink to &quot;TODO&quot;">​</a></h2><ul><li><code>read()</code>의 <code>EINTR</code> 재시도 처리</li><li>Peer가 먼저 연결을 닫을 때 발생할 수 있는 <code>SIGPIPE</code> 처리</li><li>여러 client를 순차 또는 동시 처리하는 server 구조는 이후 학습</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><code>/proc/stat</code>을 읽고 두 시점의 CPU tick 차이로 CPU usage를 계산한다.</li></ul>`,53)])])}const u=a(i,[["render",c]]);export{k as __pageData,u as default};
